describe('Checkout Flow - Full Order Confirmation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should successfully complete a full checkout and display confirmation', () => {
    // Login
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Add item to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart
    cy.get('[data-testid="shopping_cart_link"]').click();

    // Proceed to checkout
    cy.get('[data-testid="checkout"]').click();

    // Fill in checkout information
    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="postalCode"]').type('201301');

    // Continue to overview
    cy.get('[data-testid="continue"]').click();

    // Verify overview page and item total
    cy.get('[data-testid="cart-item-count"]').should('contain', '1');
    cy.get('[data-testid="item-total"]').should('contain', '$10.00');

    // Complete order
    cy.get('[data-testid="finish"]').click();

    // Verify confirmation page
    cy.get('[data-testid="complete-header"]').should('be.visible');
    cy.get('[data-testid="complete-header"]').should('contain', 'Thank you for your order!');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should handle invalid postal code and prevent checkout completion', () => {
    // Login
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Add item to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart
    cy.get('[data-testid="shopping_cart-link"]').click();

    // Proceed to checkout
    cy.get('[data-testid="checkout"]').click();

    // Fill in checkout information with invalid postal code
    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="postalCode"]').type('invalid-zip');

    // Attempt to continue
    cy.get('[data-testid="continue"]').click();

    // Verify error message appears
    cy.get('[data-testid="postal-code-error"]').should('be.visible');
    cy.get('[data-testid="postal-code-error"]').should('contain', 'Please enter a valid postal code');

    // Verify checkout is not completed
    cy.get('[data-testid="complete-header"]').should('not.exist');
    cy.get('[data-testid="cart-item-count"]').should('contain', '1');
  });
});
